function fieldsFor(id){return forms[id]||[];}
function valuesFor(id){const v={};for(const f of fieldsFor(id)){v[f.key]=typeof f.default==='function'?f.default():f.default??(f.multi?[]:f.type==='switch'?false:'')}return {...v,...(state.settings.savedForms?.[id]||{}),...state.formValues[id]};}
function formField(f,values){if(f.show&&!f.show(values))return '';const val=values[f.key],opts=typeof f.options==='function'?f.options():f.options||[];let input='';const disabled=current==='reward-rules'&&f.key!=='enabled'&&!values.enabled;const attr=`${disabled?'disabled':''} name="${f.key}" id="field-${f.key}" ${f.readonly?'readonly':''} ${f.max&&f.type!=='upload'?`maxlength="${f.max}"`:''} placeholder="${esc(f.placeholder||'请输入')}"`;
if(f.type==='textarea')input=`<textarea ${attr}>${esc(val)}</textarea><div class="counter" data-counter="${f.key}">${String(val||'').length}${f.max?'/'+f.max:''}</div>`;
else if(f.type==='select')input=`<select ${attr}><option value="">请选择</option>${opts.map(o=>`<option value="${esc(o)}" ${o===val?'selected':''}>${esc(o)}</option>`).join('')}</select>${f.link?`<button class="text-blue" data-select-page="${f.link}" data-field="${f.key}" aria-label="搜索${esc(f.label)}">⌕</button>`:''}`;
else if(f.type==='switch')input=`<button class="switch field-toggle ${val?'on':''}" data-form-switch="${f.key}" role="switch" aria-checked="${!!val}" aria-label="${esc(f.label)}"></button>`;
else if(f.type==='chips')input=`<div class="chips" style="margin-top:12px">${opts.map(o=>`<button class="chip ${(f.multi?Array.isArray(val)&&val.includes(o):val===o)?'active':''}" data-form-chip="${f.key}" data-multi="${!!f.multi}" data-value="${esc(o)}">${esc(o)}</button>`).join('')}</div>`;
else if(f.type==='upload'){const uploads=state.uploads[current]?.[f.key]||[];input=`<div class="upload-grid">${uploads.map((src,i)=>`<div class="upload-box"><img src="${esc(src)}" alt="本地附件" data-preview="${esc(src)}"><button class="remove" data-remove-upload="${f.key}" data-index="${i}" aria-label="移除图片">×</button></div>`).join('')}${uploads.length<f.max?`<label class="upload-box upload"><span class="plus">+</span><span>添加图片</span><input type="file" accept="image/*" data-upload="${f.key}" ${f.max>1?'multiple':''} hidden></label>`:''}</div><div class="upload-options"><span class="hint-inline" style="padding-left:0">最多${f.max}张</span>${act('demo-upload','使用演示图片','upload-demo',f.key)}</div>`;}
else input=`<input ${attr} type="${f.type}" value="${esc(val)}" ${f.type==='number'?'step="any"':''}>`;
const block=['textarea','chips','upload'].includes(f.type);return `<div class="field" data-field-wrap="${f.key}"><div class="field-main"><label for="field-${f.key}">${f.required?'<span class="req">*</span>':''}${esc(f.label)}</label>${block?'':input}</div>${block?input:''}<div class="field-error" hidden></div></div>`;}
function formBody(id){const v=valuesFor(id);let intro='',after='';if(id==='change-manager')intro='<div class="helper-banner">变更医助需简述原因，并按要求上传相关佐证。</div>';if(id==='ocr-upload')intro='<div class="hint">请选择所属医院，上传清晰、完整的专家墙照片。</div>';if(id==='visit-edit')intro='<div class="form-section-title">基本信息与拜访内容</div>';if(id==='schedule-edit')intro=section('上次拜访关注方向','<div class="detail-text">医生希望进一步了解平台服务，下次带来资料并协助完成使用指导。</div>');if(id==='workorder-reply')after='<div class="hint">待反馈：需要用户补充信息；待确认：告知用户已处理完成，待确认结单并评分。</div>';if(id==='thanks-production')after='<div class="hint">选择确认制作后，请填写完整收货信息。</div>';if(id==='reward-team')intro=section('',row('本周可发放兑换卡',`<span class="text-blue">${state.cards} 张</span>`));if(id==='reward-rules')after=`<div class="hint">审核、首单、次单三项权重合计 100%，新人扶持比例另计。</div>${section('配置预览',row('审核',`${Number(v.audit)||0} 积分权重`)+row('首单',`${Number(v.first)||0} 积分权重`)+row('次单',`${Number(v.second)||0} 积分权重`))}`;if(id==='order-refund')intro=section('订单信息',row('订单号',order().id)+row('实付金额','¥ '+order().money));if(id==='pk-create')after=section('队伍成员',go('pk-team-select',`<span class="row" style="width:100%">选择队员 <span class="value">${state.selectedMembers.length?'已选择 '+state.selectedMembers.join('、'):'请选择'}</span><span class="chevron">›</span></span>`))+state.selectedMembers.map((m,i)=>row(`${i===0?'队长':'队员'} ${m}`,`${act('member-up','↑','text-blue',i)}　${act('member-down','↓','text-blue',i)}`)).join('');return `${intro}<form id="native-form" novalidate><div class="form-group">${fieldsFor(id).map(f=>formField(f,v)).join('')}</div>${after}<button type="submit" class="primary-btn">${{'ocr-upload':'开始识别','order-address':'确认修改','order-invoice':'提交','order-refund':'提交','order-complaint':'提交','workorder-create':'确定','workorder-reply':'确定','workorder-return':'确定','workorder-transfer':'确定','workorder-finish':'确定','special-qualifications':'提交审核','reward-team':'发放','thanks-production':'确认','pk-create':'发起对战'}[id]||'保存'}</button>${['schedule-edit','birthday'].includes(id)?act('delete-schedule','删除','settings-logout'):''}</form>`;}
function readForm(){const v=valuesFor(current),form=$('#native-form');if(!form)return v;for(const [key,value]of new FormData(form).entries())v[key]=String(value).trim();state.formValues[current]=v;save();return v;}
function validateForm(id,v){let first=null;$$('.field.invalid').forEach(e=>e.classList.remove('invalid'));$$('.field-error').forEach(e=>{e.hidden=true;e.textContent=''});const errors={};for(const f of fieldsFor(id)){if(f.show&&!f.show(v))continue;if(id==='reward-rules'&&f.key!=='enabled'&&!v.enabled)continue;const val=v[f.key];let error='';if(f.type==='upload'){if(f.required&&!(state.uploads[id]?.[f.key]?.length))error='请添加'+f.label;}else if(f.required&&(!val||(Array.isArray(val)&&!val.length)))error='请'+(['select','chips'].includes(f.type)?'选择':'填写')+f.label;else if(val&&f.type==='tel'&&!/^1\d{10}$/.test(val))error='请输入正确的手机号';else if(val&&f.type==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val))error='请输入正确的邮箱地址';else if(f.minLength&&String(val||'').length<f.minLength)error=f.label+'至少输入'+f.minLength+'个字';else if(val!==''&&f.type==='number'&&(Number(val)<(f.min??-Infinity)||Number(val)>(f.max??Infinity)||!Number.isFinite(Number(val))))error=`请输入${f.min??0}至${f.max??'有效范围内'}的数值`;else if(f.integer&&!Number.isInteger(Number(val)))error='请输入整数';if(error)errors[f.key]=error;}
if(id==='reward-rules'&&v.enabled&&Number(v.audit)+Number(v.first)+Number(v.second)!==100)errors.second='审核、首单、次单三项总和需为100%';if(id==='reward-team'&&Number(v.count)>state.cards)errors.count='发放数量不能超过可用兑换卡数';if(id==='pk-create'){if(v.end<v.start)errors.end='结束时间不得早于开始时间';if(state.selectedMembers.length<2)errors.teamA='请至少选择两名队员';}for(const [key,msg]of Object.entries(errors)){const wrap=$(`[data-field-wrap="${key}"]`);if(wrap){wrap.classList.add('invalid');const error=wrap.querySelector('.field-error');error.textContent=msg;error.hidden=false;if(!first)first=wrap}}if(Object.keys(errors).length){first?.scrollIntoView({block:'center',behavior:'smooth'});toast(Object.values(errors)[0]);return false}return true;}
function submitForm(){const id=current,v=readForm();if(!validateForm(id,v))return;const done=()=>{if(['doctor-potential','doctor-service-fee','birthday','reward-rules'].includes(id)){state.settings.savedForms??={};state.settings.savedForms[id]={...v};}if(id==='doctor-add'&&state.editingDoctor){state.doctorEdits??={};state.doctorEdits[doctor().name]={...v,status:doctor().status,tags:doctor().tags};state.editingDoctor=false;}else if(id==='doctor-add'){state.newDoctors.unshift({name:v.name,department:v.department,title:v.title,hospital:v.hospital,level:v.level,status:'未注册',phone:v.phone,orders:0,days:0,tags:['资料已建档']});state.selectedDoctor=0;}if(id==='doctor-potential')state.settings.potential=v;if(id==='doctor-service-fee')state.settings.serviceFee=v;if(id==='doctor-tags-edit')state.tags=Array.isArray(v.tags)?v.tags:state.tags;if(id==='change-manager')state.settings.doctorManager=v.manager;if(id==='visit-edit')state.visits.unshift({...v,id:Date.now()});if(id==='schedule-edit')state.schedules.unshift({...v,id:Date.now()});if(id==='order-address')state.address={...v};if(id==='order-invoice')state.orderInvoice=true;if(id==='order-refund')state.orderRefund=true;if(id==='workorder-create'){state.workorders.unshift({name:v.name,content:v.content,status:'待反馈',time:'刚刚',id:'WO'+Date.now()});state.workDeleted=false;state.workStatus='待反馈';}if(id==='workorder-reply'){state.workMessages.push({text:v.content,self:true,time:'刚刚'});state.workStatus=v.next.includes('确认')?'待确认':'待反馈';}if(id==='workorder-return'){state.workStatus='已退回';state.workMessages.push({text:'已退回：'+v.content,self:true,time:'刚刚'});}if(id==='workorder-transfer'){state.workStatus='已转派';state.workMessages.push({text:'转派给'+v.person+'：'+v.content,self:true,time:'刚刚'});}if(id==='workorder-finish'){state.workStatus='已完成';state.settings.evaluation=v.evaluation;state.settings.resolved=v.resolved;}if(id==='reward-team'){state.cards-=Number(v.count);state.received.unshift({name:v.manager,count:v.count});}if(id==='thanks-production')state.thanksStatus=v.production==='确认制作'?'待制作':'已确认不制作';if(id==='pk-create')state.pkEntries.unshift({...v,members:state.selectedMembers.slice()});if(id==='ocr-upload')state.ocrDone=true;save();state.formValues[id]=undefined;navigate(formBack[id]||'mine');toast(id==='ocr-upload'?'识别完成，已展示演示结果':'保存成功（本地演示）');};
if(['order-refund','workorder-finish','workorder-return','change-manager','thanks-production','reward-team'].includes(id))confirm({'order-refund':'确认提交退款申请？','workorder-finish':'确认完成工单？','workorder-return':'确认退回工单？','change-manager':'确认变更跟进医助？','thanks-production':'确认提交制作信息？','reward-team':'确认发放兑换卡？'}[id],id==='thanks-production'&&v.production==='不制作'?'不制作将进入相关退款申请流程。当前仅更新本地演示状态。':'请核对填写内容，本次操作只更新当前原型的演示数据。',done);else done();}
function doctorCard(d,i,options={}){const claimed=state.claimed.includes(d.name),isResource=options.resource,needCard=current==='reward-pool';return `<article class="doctor-card"><div class="doctor-card-top" data-doctor="${i}" data-target="${options.target||(isResource?'other-doctor-home':'doctor-home')}">${avatar(d.name)}<div style="flex:1"><div class="name">${esc(d.name)} ${pill(d.level,'orange')} ${d.status==='未注册'?pill('未注册','gray'):''}</div><div class="hospital">${esc(d.title)} · ${esc(d.department)}<br>${esc(d.hospital)}</div></div>${act('call','♧','text-blue',d.phone)}</div><div class="chips">${(d.tags||[]).map(t=>pill(t,t.includes('未')?'orange':'')).join('')}${state.protected.includes(d.name)?pill('保护中','green'):''}</div>${options.potential?`<div class="card-metrics"><span>患者数量 <b>${i===0?'较高':'中等'}</b></span><span>开方潜力 <b>${i===0?'较高':'中等'}</b></span><span>${act('potential-reason','推荐原因','text-blue',d.name)}</span></div>`:`<div class="card-metrics"><span>本月开方 <b>${d.orders}单</b></span><span>距上次跟进 <b>${d.days}天</b></span><span>${esc(d.status)}</span></div>`}${isResource?`<div style="display:flex;justify-content:space-between;align-items:center;padding-top:12px"><span style="font-size:10px;color:#a5afbd">${needCard?'需 2 张兑换卡':'客户资源'}</span><div>${act('protect',state.protected.includes(d.name)?'取消保护':'设为保护','text-blue',d.name)}　${act('claim',claimed?'已领取':'领取医生','action-link',d.name)}</div></div>`:''}</article>`;}
function doctorList(p){let ds=allDocs().map((d,i)=>({d,i}));const q=state.queries[current]||state.queries['doctor-search']||'';if(p.id.includes('results')&&q)ds=ds.filter(x=>[x.d.name,x.d.phone,x.d.hospital].join(' ').includes(q));if(p.id==='doctors'){const category=['全部','待激活','已激活','已流失','未注册'][state.tabs.doctors||0];if(category!=='全部')ds=ds.filter(x=>x.d.status===category)}const f=state.filters[p.id]||{};const status=f['活跃状态']||f['状态'];if(status&&status!=='全部'&&['待激活','已激活','已流失','未注册'].includes(status))ds=ds.filter(x=>x.d.status===status);if(f['职称']&&f['职称']!=='全部')ds=ds.filter(x=>x.d.title===f['职称']);if(f['医生等级']&&f['医生等级']!=='全部')ds=ds.filter(x=>x.d.level===f['医生等级']);if(f['标签']&&f['标签']!=='全部')ds=ds.filter(x=>(x.d.tags||[]).includes(f['标签']));if(f['状态']==='已领取')ds=ds.filter(x=>state.claimed.includes(x.d.name));if(f['状态']==='未领取')ds=ds.filter(x=>!state.claimed.includes(x.d.name));if(f['排序']==='开方数从高到低')ds.sort((a,b)=>b.d.orders-a.d.orders);if(f['排序']==='距上次拜访从远到近')ds.sort((a,b)=>b.d.days-a.d.days);const resource=['doctor-pools','pool-results','protected-doctors','potential-doctors','reward-pool'].includes(p.id);if(p.id==='protected-doctors')ds=ds.filter(x=>state.protected.includes(x.d.name));let head='';if(p.id==='reward-pool')head=section('',row('兑换卡',`<span class="text-blue">${state.cards} 张</span>`,'reward-cards')+row('规则说明','','@reward-rules'));if(p.id==='potential-doctors')head='<div class="helper-banner">基于客户潜力信息查找适合跟进的医生</div>';if(p.id==='doctor-pools')head=`<div class="mini-nav">${go('protected-doctors','已保护名单','text-blue')} ${go('potential-doctors','查看潜力医生 ›','text-blue')}</div>`;
const filterLabels=p.id==='doctors'?['排序','状态','职称','地点','筛选']:p.id==='potential-doctors'?['排序','地区','筛选']:p.id==='reward-pool'?['奖励池区域','状态']:resource?['范围','释因','职称','地点','筛选']:['状态','职称','地点','筛选'];return {top:`${p.id==='doctors'?tab(['全部','待激活','已激活','已流失','未注册'],'doctors'):''}${filters(filterLabels)}`,body:head+`<div class="result-count"><span>共 ${ds.length} 个结果</span>${p.id==='doctor-pools'?'<span>私有池演示</span>':''}</div>`+(ds.length?ds.map(({d,i})=>doctorCard(d,i,{resource,potential:p.id==='potential-doctors'})).join(''):'<div class="empty-state"><div class="empty-graphic">◇</div>暂无相关医生</div>')+end(),floating:p.id==='doctors'?go('doctor-add','+','floating-add'):''};}
function orderCard(o,i,target='order-detail'){return `<article class="order-card" data-order="${i}" data-target="${target}"><div class="order-card-head"><span>${esc(o.id)}</span><span class="text-blue">${state.orderRefund&&i===state.selectedOrder?'退款申请中':esc(o.status)}</span></div><div class="order-main"><b>${esc(o.doctor)} <small class="muted" style="font-weight:400">（青禾）</small></b><span>患者 ${esc(o.patient)}</span></div><div class="order-line"><span>${o.type} · 7 剂 · 示例药房</span><span>¥ ${o.money}</span></div><div class="order-foot"><span>${o.time}</span><span>${state.followed.includes(o.id)?'★ 已关注':'查看详情 ›'}</span></div></article>`;}
function orderList(p){let list=orderData.map((o,i)=>({o,i}));if(p.id==='focused-orders')list=list.filter(x=>state.followed.includes(x.o.id));const f=state.filters[p.id]||{};if(f['付款']==='待支付')list=list.filter(x=>x.o.status==='待支付');if(f['付款']==='已支付')list=list.filter(x=>x.o.status!=='待支付');if(f['物流']&&f['物流']!=='全部')list=list.filter(x=>x.o.status===f['物流']);if(f['剂型']&&f['剂型']!=='全部')list=list.filter(x=>x.o.type===f['剂型']);const searchQuery=state.queries['order-search']||state.queries['mall-search'];if(p.id.includes('results')&&searchQuery)list=list.filter(x=>Object.values(x.o).join(' ').includes(searchQuery));if(p.id==='urgent-orders'){const t=state.tabs[p.id]||0;if(t===1)list=list.filter(x=>x.o.status==='待发货');if(t===2)list=list.filter(x=>x.o.status==='已发货');if(t===3)list=[];}let target=p.id.startsWith('mall')?'mall-detail':p.id.startsWith('photo')?'photo-order-detail':'order-detail';let bar=p.id==='urgent-orders'?tab(['全部','应发未发','发货超时','收货异常']):p.id==='photo-orders'?tab(['全部','待录方','待复核','待医生确认','已处理','已取消']):'';const filterLabels=p.id.startsWith('mall')?['最近30天']:['付款','物流','剂型','筛选'];return {top:bar+filters(filterLabels),body:`<div class="result-count"><span>共 ${list.length} 个结果</span>${act('date-filter',state.filters[current]?.['日期']||'最近30天')}</div>`+(list.length?list.map(({o,i})=>orderCard(o,i,target)).join(''):'<div class="empty-state"><div class="empty-graphic">◇</div>暂无相关订单</div>')+end()};}
function statsHeader(title,range='今日 | 个人'){range=state.settings.metricScope||range;return `<div class="blue-hero"><div class="hero-title"><span>${title}</span>${act('metric-scope',range+' ⌄')}</div><div class="hero-compact">${go('orders','<small>药方业绩（元）</small><b>28,640.00</b>')}${go('doctor-metric-list','<small>新审核医生</small><b>12</b>')}${go('doctor-metric-list','<small>次单医生</small><b>8</b>')}</div><div style="text-align:center;padding-top:12px">${act('expand-metrics',state.settings.expandedMetrics?'⌃':'⌄')}</div>${state.settings.expandedMetrics?`<div class="hero-stats">${go('orders','<small>付款药方</small><strong>86 单</strong>','hero-stat')}${go('mall-data','<small>商城业绩</small><strong>2,460</strong>','hero-stat')}${go('doctor-metric-list','<small>累计医生</small><strong>128</strong>','hero-stat')}</div>`:''}</div>`;}
const appGroups=[['订单',[['orders','订单查询','apply_order'],['urgent-orders','紧急订单','apply_urgency'],['focused-orders','关注订单','apply_focus'],['after-sales','售后投诉','apply_after_sale'],['workorders','协同工单','apply_synergy'],['inquiry-orders','问诊订单','apply_chat'],['consultations','咨询订单','apply_ask'],['drug-storage','药库查询','apply_medicine']]],['数据',[['team-data','团队数据','apply_team'],['doctor-board','医生数据','apply_data'],['huashan','华山论剑','apply_huashan'],['pk-center','皇城PK','apply_pk'],['runoff-warning','流失预警','apply_warning'],['operation-miniapp','运营有道','apply_uniapp']]],['医生',[['doctor-pools','私有池','apply_private'],['doctor-pools','公有池','apply_pond','public'],['visit-all','拜访记录','apply_record'],['reward-pool','奖励池','reward_icon'],['potential-doctors','慧眼寻医','apply_eye']]],['其他',[['materials','业务资料','apply_file']]]];
function menuGrid(items,cols=''){return `<div class="icon-grid ${cols}">${items.map(([id,label,img,special])=>`<button class="grid-item" ${special?`data-pool="${special}"`:`data-go="${id}"`}>${icon(img,label.slice(0,1))}<span>${label}</span>${id==='urgent-orders'?'<i>3</i>':''}</button>`).join('')}</div>`;}
const quickItems=[['doctor-check','查验医生','checkdoctor_icon'],['doctor-invite','邀请医生','invite_doctor'],['doctor-audit','医生审核','doctor_audit'],['doctor-add','新增医生','add_doctor'],['nearby-map','雾影寻踪','miss_icon'],['visit-edit','添加拜访','add_record'],['schedule-edit','创建日程','creat_schedule_icon'],['doctor-register-code','注册验证','auth_code'],['activities','运营活动','activity_icon']];
function renderHome(){const metric=state.filters.home?.['行为']||'开方';return {top:tab(['首页','通知','工单'],'home', ['home','notification','workorders']),body:`<div class="mini-nav"><button data-filter="行为">${esc(metric)} ⌄</button>${go('doctor-search','⌕ 搜索医生','text-blue')}</div><div style="overflow:auto;background:white"><table class="data-table"><thead><tr><th>医生</th><th>今日</th><th>昨日</th><th>最近7天</th><th>环比</th><th>最近30天</th></tr></thead><tbody>${allDocs().map((d,i)=>`<tr><td><button data-doctor="${i}">${d.name}</button></td>${[2+i,4+i,18+i*2,'+12%',68+i*5].map(x=>`<td><button data-act="home-metric" data-value="${i}">${x}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="hint">左右滑动查看更多数据，点击医生查看主页。</div>${section('近期关注',row('待审核医生','3 位','doctor-audit')+row('即将拜访','2 位','calendar')+row('待处理协同','2 条','workorders'))}`};}
const todoData=[{id:0,title:'订单发货进度跟进',text:'陈明医生的订单已发货，请关注物流状态。',time:'09:00',target:'order-detail'},{id:1,title:'医生资料待完善',text:'林静医生的资质资料需补充，协助完成审核。',time:'09:30',target:'special-qualifications'},{id:2,title:'协同工单待确认',text:'订单服务事项已处理，请确认并评价。',time:'10:10',target:'workorder-chat'},{id:3,title:'医生回访提醒',text:'周远医生本周需要回访，记录近期使用情况。',time:'14:00',target:'visit-edit'}];
function todoRows(done=false){const list=todoData.filter(t=>state.doneTodo.includes(t.id)===done);return list.length?list.map(t=>`<div class="todo-row"><button class="todo-check ${done?'done':''}" data-act="todo-toggle" data-value="${t.id}" aria-label="${done?'恢复待办':'完成待办'}">${done?'✓':''}</button><div class="todo-content" data-go="${t.target}"><b>${t.title}</b><p>${t.text}</p><small>2026-11-06 ${t.time}</small></div></div>`).join(''):'<div class="empty-state">暂无相关待办</div>';}
function visitRows(){const sample=[...state.visits,{doctor:doctor().name,date:'2026-11-04',way:'线下',purpose:'日常维护',content:'沟通近期门诊情况，了解平台使用需求，约定下次提供服务资料。',nextFocus:'跟进首次开方情况',hospital:doctor().hospital},{doctor:'林静',date:'2026-11-02',way:'电话',purpose:'注册与审核跟进',content:'与医生核对资料提交情况，协助了解审核流程。',nextFocus:'补齐资质资料'}];return sample.map((v,i)=>`<article class="visit-card" data-act="view-visit" data-value="${i}"><div class="date"><span>${esc(v.date)} · ${esc(v.way)}</span><span>青禾</span></div><h4>${esc(v.doctor)} <span class="pill">${esc(v.purpose)}</span></h4><p>${esc(v.content)}</p><div class="bottom"><span>下次关注：${esc(v.nextFocus||'暂无')}</span><span>详情 ›</span></div></article>`).join('');}
function workbench(){return {top:'',body:section('',menuGrid(quickItems))+section('我的待办',todoRows(false),go('todo','查看全部 ›','text-blue'))+`<div class="mini-nav"><span>2026年11月6日　星期五</span>${go('calendar','甘草日历 ›','text-blue')}</div>${tab(['全部(4)','协同(1)','日程(2)','生日(1)'],'workday')}${workDayItems()}`};}
function workDayItems(){const index=state.tabs.workday||0;const rows=[];if(index===0||index===1)rows.push(`<article class="visit-card" data-go="workorder-chat"><div class="date">10:00 ${pill('协同','orange')}</div><h4>订单服务协同</h4><p>订单相关服务问题，等待确认处理结果。</p></article>`);if(index===0||index===2)rows.push(...[...state.schedules,{doctor:doctor().name,date:'2026-11-06',period:'下午',way:'线下',remark:'了解门诊情况，跟进平台使用。'},{doctor:'林静',date:'2026-11-06',period:'上午',way:'电话',remark:'跟进审核资料补充进度。'}].map(v=>`<article class="visit-card" data-go="schedule-detail"><div class="date">${esc(v.date)} ${esc(v.period||'下午')} ${pill(v.way||'线下')}</div><h4>${esc(v.doctor)}</h4><p>${esc(v.remark||'客户日常跟进')}</p></article>`));if(index===0||index===3)rows.push(`<article class="visit-card" data-go="birthday"><div class="date">2026-11-08 ${pill('生日','orange')}</div><h4>陈明医生生日提醒</h4><p>提前准备生日祝福与客户关怀。</p></article>`);return rows.join('')+end();}
function doctorHome(other=false){const d=doctor();const key=other?'other-profile':'doctor-profile';const active=state.tabs[key]||0;let body='';if(active===0)body=visitRows();if(active===1)body=other?behaviorBody():incomeBody();if(active===2)body=behaviorBody();if(active===3)body=accountBody();return {body:`<div class="profile-head"><div class="profile-top">${avatar(d.name)}<div style="flex:1"><div class="profile-name">${esc(d.name)} ${pill(d.level,'orange')} ${pill(d.status)}</div><div class="profile-sub">${esc(d.title)} · ${esc(d.department)}<br>${esc(d.hospital)}</div></div>${act('call','☎','text-blue',d.phone)}</div><div class="chips" style="margin-top:14px">${state.tags.map(s=>go('doctor-tags',esc(s),'pill')).join('')}</div><div class="profile-links">${go('doctor-potential','潜力信息 ›')}${go('doctor-tags','标记信息 ›')}${go('doctor-info','医生资料 ›')}</div></div>${other?`<div class="mini-nav"><span>${state.claimed.includes(d.name)?'已领取至我的医生':'当前为其他范围医生'}</span>${act('claim',state.claimed.includes(d.name)?'已领取':'领取该医生','text-blue',d.name)}</div>`:''}${tab(other?['拜访记录','行为跟踪']:['拜访记录','收入统计','行为统计','账户信息'],key)}${body}`,bottom:footer([{go:'visit-edit',text:'添加拜访',cls:'primary'},{go:'schedule-edit',text:'创建日程'}])};}
function behaviorBody(){return section('整体开方',`<div class="data-metrics">${[['药费（元）','6,820'],['订单数','28'],['支付用户数','18']].map(([l,v])=>go('doctor-income-orders',`<b>${v}</b><span>${l}</span>`,'metric')).join('')}</div>${chart()}`,'本月')+section('拉新能力',row('新增首单用户数','8','scan-patients')+row('新增用户数','12','scan-patients')+row('新扫码用户数','16','scan-patients'))+section('转化能力与患者粘性',row('订单支付率','86.7%')+row('复购率','42.3%')+row('累计邀请医生','5 位','invited-records'))+section('患者感谢',row('患者感谢管理','3 条','thanks'));}
function incomeBody(){return section('',`<div class="data-metrics">${[['诊金收入','1,260.00'],['开方金额','6,820.00'],['商城收入','186.00']].map(([l,v])=>go('doctor-income-orders',`<b>${v}</b><span>${l}</span>`,'metric')).join('')}</div>`)+section('收入趋势',chart([40,50,30,75,50,65,82]))+section('收入明细',row('普通方','4,280.00 元','doctor-income-orders')+row('颗粒剂','1,860.00 元','doctor-income-orders')+row('膏方','680.00 元','doctor-income-orders')+row('医生收支明细','','doctor-income-flow')+row('月对账','','month-bills'));}
function accountBody(){return section('活动',row('医生类型',state.settings['医生类型']||'普通医生','@account-option')+row('活动类型',state.settings['活动类型']||'平台活动','@account-option')+row('非平台活动',state.settings['非平台活动']||'未设置','@account-option'))+section('账户',row('账户余额','¥ 1,280.00','month-bills')+row('历史税前收入','¥ 18,640.00','doctor-income-flow')+row('月对账','','month-bills')+row('纳税方式',state.settings.taxType||'代扣代缴','@tax-option')+row('缴税方式历史记录','','tax-history')+row('是否上传身份证','是')+row('是否绑定银行卡','是'))+section('优惠券',`<div class="data-metrics">${['待使用','已使用','已过期'].map((l,i)=>`<button class="metric" data-coupon-tab="${i}"><b>${[5+state.gifts.length,3,12][i]}</b><span>${l}</span></button>`).join('')}</div>`+row('赠送优惠券','','coupon-gift'))+section('服务与配置',row('医生关注','选择关注行为','doctor-attention')+row('生成台签物料','去生成','doctor-materials')+row('医生服务费配置','去修改','doctor-service-fee')+row('服务费等级','B级','service-level-history')+['是否隐藏收入','开通照片方','开通协定方','经方验方','隐身功能'].map(l=>`<div class="row"><span class="label">${l}</span><span style="margin-left:auto">${act('account-toggle','',`switch ${state.settings[l]?'on':''}`,l)}</span></div>`).join('')+row('删除/恢复患者','','@patient-menu')+row('第三方微信提现渠道','默认渠道','@account-option')+row('医生版本','3.0.0'));}
function doctorInfo(){const d=doctor();return section('',row('资质是否完整','不完整','special-qualifications')+row('审核状态','已审核','audit-record-detail')+row('所属医助',esc(state.settings.doctorManager||'青禾'),'change-manager')+row('公私海',state.settings.releasedDoctor===doctor().name?'公有池':'私有池','@release-doctor'))+section('基本信息',row('姓名',esc(d.name))+row('手机号',esc(d.phone),'@call')+row('性别','男')+row('出生日期','1980-11-08','birthday')+row('科室',esc(d.department))+row('职称',esc(d.title))+row('执业地点',esc(d.hospital))+row('执业省市','浙江省 杭州市')+row('拜访地址',state.settings.mapAddress||'示例路18号','visit-address'))+section('其他信息',row('特殊分类','普通医生')+row('继承关系','非继承')+row('医生来源','自主开发')+row('医生类型','执业医师'))+act('doctor-delete','删除医生资料','settings-logout');}
function notificationBody(){return section('',row('通知小助手','6 条新消息','notification-helper'))+allDocs().slice(0,4).map((d,i)=>`<article class="notice-card" data-doctor="${i}" data-target="doctor-messages"><h4><span>${esc(d.name)}</span><time>${['09:25','昨天','11-04','11-03'][i]}</time></h4><p>${['新增开方记录，请关注支付情况。','医生资质资料待补充。','收到新的协同服务消息。','客户近期未开单，请及时跟进。'][i]}</p>${pill(i<2?'未读':'已读',i<2?'orange':'gray')}</article>`).join('')+end();}
function calendarBody(){const days=new Date(state.year,state.month,0).getDate(),start=(new Date(state.year,state.month-1,1).getDay()+6)%7;return `<div class="calendar-head">${act('month-prev','‹')}<strong>${state.year}年${state.month}月</strong>${act('month-next','›')}</div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(x=>'<span>'+x+'</span>').join('')}${Array(start).fill('<span></span>').join('')}${Array.from({length:days},(_,i)=>`<button data-day="${i+1}" class="${state.day===i+1?'selected':''} ${[6,7,8,12,15,20,24].includes(i+1)?'has-event':''}">${i+1}</button>`).join('')}</div>${tab(['全部','日程','生日'],'calendar-items')}<div class="title-note">${state.year}-${String(state.month).padStart(2,'0')}-${String(state.day).padStart(2,'0')} 的安排</div>${state.day===6||state.schedules.some(s=>Number(s.date.split('-')[2])===state.day)?workDayItems():`<div class="empty-state" style="min-height:180px"><span>暂无日程安排，快去创建日程吧</span>${go('schedule-edit','创建日程','retry')}</div>`}`;}
function orderDetail(mall=false,photo=false){const o=order(),addr=state.address;let top=`<div class="order-state"><div><strong>${photo?'待医生确认':state.orderRefund?'退款申请中':o.status}</strong><p>${photo?'请关注照片方处理进度':'订单服务与履约信息'}</p></div><span>${photo?'▧':'▱'}</span></div>`;let infoRows=row('订单编号',esc(o.id),'@copy-order')+row('物流状态',esc(o.status),'order-logistics')+row(mall?'推荐医生':'医生信息',esc(o.doctor),'doctor-home')+row('患者信息',esc(o.patient)+'　'+act('call','联系','text-blue','13800000000'))+row('下单时间',o.time)+row('支付时间',o.status==='待支付'?'暂无':o.time)+row('医嘱/备注','请遵医嘱使用');if(!mall)infoRows+=row('药方剂型',o.type)+row('剂数','7剂')+row('药方服法','每日一剂，分次服用')+row('临床诊断','演示诊断内容')+row('药库','示例药房');infoRows+=row('收件地址',`${esc(addr.name)} ${esc(addr.phone)}<br>${esc(addr.region)} ${esc(addr.detail)}`,'order-address');let details=section('订单信息',infoRows);if(photo)details+=section('开方图片','<div class="detail-text"><button class="attachment-demo" style="width:100%" data-act="preview-image">▧　查看开方图片</button></div>');if(mall)details+=section('商品信息',row('商品名称','示例健康商品 × 1')+row('规格','标准装'));if(!photo)details+=section('价格明细',row('实付',`<span class="text-red">¥ ${o.money}</span>`,'@price-details')+(state.settings.priceExpanded?row('药价','¥ 206.00')+row('服务费','¥ 60.00')+row('运费','¥ 10.00')+row('制作费','¥ 20.00')+row('优惠金额','- ¥ 10.00'):''))+section('物流信息',row('承运公司','示例快递','order-logistics')+row('快递单号','SF000000000000','@copy-tracking'))+section('服务信息',row('退款信息',state.orderRefund?'申请处理中':'暂无','after-sales')+row('协同工单','1 条','workorders')+row('售后投诉','','order-complaint')+row('用药单详情','','order-image')+row('药方溯源','','order-prescription-trace'))+section('备注',row('医生备注','本地演示信息')+row('患者留言','请提前联系收货')+row('客服备注','暂无'));return {body:top+details,bottom:photo?footer([{go:'doctor-home',text:'医生主页',cls:'primary'},{act:'preview-image',text:'查看开方图片'}]):footer([{act:'follow-order',text:state.followed.includes(o.id)?'已关注':'＋关注'},{go:'workorder-create',text:'发起协同',cls:'primary'},{go:'order-complaint',text:'售后投诉'}])};}
function workorderCards(){if(state.workDeleted&&!state.workorders.length)return '<div class="empty-state"><div class="empty-graphic">◇</div>暂无工单</div>';const list=[...state.workorders,{name:'订单服务协同',content:'医生反馈物流信息需核对，请协助跟进。',status:state.workStatus,time:'2026-11-06 09:20',id:'WO202611060001'},{name:'医生资料协同',content:'协助补齐资质资料，推进后续审核。',status:'待反馈',time:'2026-11-05 15:40',id:'WO202611050002'}];return list.map((w,i)=>`<article class="notice-card" data-work="${i}"><h4>${esc(w.name)}${pill(i===0?state.workStatus:w.status,w.status==='已完成'?'green':'orange')}</h4><p>${esc(w.content)}</p><time>${esc(w.id)} · ${esc(w.time)}</time><div style="font-size:10px;color:#a3afbf;margin-top:10px">发起人：青禾　跟进人：小川</div></article>`).join('');}
function workorderInfo(){const status=state.workStatus;return section('工单信息',row('工单名称',state.workorders[0]?.name||'订单服务协同')+row('工单状态',pill(status,status==='已完成'?'green':'orange'))+row('工单号','WO202611060001')+row('发起人','青禾')+row('创建时间','2026-11-06 09:20')+row('跟进人','小川'))+section('协同信息',row('关联订单',order().id,'order-detail')+row('医生',doctor().name,'doctor-home')+row('联系电话',act('call','13800000000','text-blue','13800000000'))+`<div class="detail-text">请协助核对订单服务进度，并及时反馈处理结果。</div>`)+(status==='已完成'?section('工单评价',row('评价',esc(state.settings.evaluation||'满意'))+row('是否解决',esc(state.settings.resolved||'已解决'))):'')+section('处理记录',row('查看全部处理记录','','workorder-chat'));}
function workActionButtons(){if(state.workStatus==='已完成')return '';const c=state.workRole==='creator'?[{go:'workorder-reply',text:'回复',cls:'primary'},...(state.workStatus==='待确认'?[{go:'workorder-finish',text:'完成',cls:'primary'}]:[])]:state.workRole==='follower'?[{go:'workorder-return',text:'退回'},{go:'workorder-transfer',text:'转派'},{go:'workorder-reply',text:'回复',cls:'primary'}]:[{go:'workorder-reply',text:'回复',cls:'primary'}];return footer(c);}
function chatBody(inquiry=false){const messages=inquiry?[{text:'医生您好，想了解一下近期的调理建议。',self:false,name:'演示患者'},{text:'请补充一下近期情况及相关资料。',self:true,name:'演示医生'},{text:'已补充资料，请您查看。',self:false,name:'演示患者'}]:[{text:'请协助核对本次订单的物流信息，医生希望了解预计送达时间。',self:true,name:'青禾'},{text:'已联系服务人员核对，订单已正常发出，会继续关注配送进度。',self:false,name:'小川'},{text:'物流信息已更新，请确认处理结果。',self:false,name:'小川'},...state.workMessages];return `<div class="chat-area"><div class="chat-time">2026年11月6日 09:20</div>${messages.map(m=>`<div class="chat-message ${m.self?'self':''}">${avatar(m.name|| (m.self?'青禾':'小川'),'small')}<div><small>${esc(m.name|| (m.self?'青禾':'小川'))}${m.time?' · '+esc(m.time):''}</small><div class="bubble">${esc(m.text||'')}${m.image?`<img src="${esc(m.image)}" alt="演示附件" style="max-width:180px;max-height:180px;display:block" data-preview="${esc(m.image)}">`:''}${m.file?go('attachment-preview','▱ 订单服务说明.pdf','text-blue'):''}</div></div></div>`).join('')}${!inquiry?`<div class="chat-message">${avatar('小川','small')}<div><small>小川</small><div class="bubble">${go('attachment-preview','▱ 订单服务说明.pdf','text-blue')}</div></div></div>`:''}${state.workStatus==='已完成'&&!inquiry?'<div class="chat-time">工单已完成</div>':''}</div>`;}
function inquiryList(p){const isNew=p.id.startsWith('consultation');const q=state.queries[isNew?'consultation-search':'inquiry-search']||'';return {top:isNew?filters(['最近30天']):tab(['全部','待完善','待回复','待开方','已退款'])+filters(['最近30天','排序']),body:`<div class="result-count">共 ${isNew?'5':'4'} 个结果</div>`+allDocs().slice(0,4).map((d,i)=>({d,i})).filter(({d,i})=>!q||[d.name,'ZX20261106000'+(i+1),['李女士','王先生','赵女士','刘先生'][i]].join(' ').includes(q)).filter(({i})=>isNew||!(state.tabs[p.id]||0)||['待回复','待完善','待开方','已退款'][i]===['全部','待完善','待回复','待开方','已退款'][state.tabs[p.id]]).map(({d,i})=>isNew?`<article class="notice-card"><h4><button data-doctor="${i}">${esc(d.name)} <span class="muted" style="font-size:11px">（青禾）</span></button><span class="pill gray">${['李女士','王先生','赵女士','刘先生'][i]}</span></h4><p>${i%2?'诊后咨询':'扫码咨询'} · ZX20261106000${i+1}</p><time>2026-11-06 09:${20+i*5}:00</time></article>`:`<article class="notice-card" data-go="inquiry-detail"><h4>${esc(d.name)}${pill(['待回复','待完善','待开方','已退款'][i],i===3?'gray':'orange')}</h4><p>患者：${['李女士','王先生','赵女士','刘先生'][i]}　咨询费 ¥ 20.00</p><time>ZX20261106000${i+1} · 2026-11-06 09:20</time></article>`).join('')+end()};}
function materialList(){return {top:filters(['资料类型']),body:`<div class="result-count"><span>共 6 个结果</span></div>`+[['活动推广资料说明.pdf','pdf','活动资料','2026-11-03'],['产品介绍手册.pdf','pdf','产品资料','2026-10-28'],['客户沟通记录模板.doc','doc','培训资料','2026-10-20'],['业务信息登记表.xlsx','xls','业务资料','2026-10-16'],['平台服务说明.pdf','pdf','产品资料','2026-10-10'],['培训课程提纲.doc','doc','培训资料','2026-10-05']].filter(x=>!state.queries['material-search']||x[0].includes(state.queries['material-search'])).filter(x=>!state.filters.materials?.['资料类型']||state.filters.materials['资料类型']==='全部'||x[2]===state.filters.materials['资料类型']).map(([name,type,category,date])=>`<article class="file-card" data-go="attachment-preview"><span class="file-icon ${type}">${type.toUpperCase()}</span><div><div class="file-title">${name}</div><div class="file-meta">${category} · ${date} 上传</div></div><span style="margin-left:auto;color:#b5c0cd">›</span></article>`).join('')+end()};}
function couponList(gift=false){const idx=state.tabs.coupons||0,available=[{amount:50,name:'首方专享券（医生）',condition:'无门槛',type:'普通方',valid:'2026-11-01 至 2026-12-01'},{amount:30,name:'福利开方券（患者）',condition:'满300元可用',type:'普通方',valid:'2026-11-01 至 2026-11-30'},{amount:9,name:'首单福利开方券（医生）',condition:'满2000元可用',type:'膏方',valid:'2026-11-01 至 2026-12-01'}];return {top:gift?'':tab(['待使用(5)','已使用(3)','已过期(12)'],'coupons'),body:gift?section('',row('可赠送额度','¥ 200.00'))+'<div class="form-section-title">可赠送优惠券</div>'+available.map((c,i)=>coupon(c,i,true)).join('')+'<div class="form-section-title">过期优惠券重新发放</div>'+coupon({...available[0],name:'过期首单券重新发放'},3,true):available.map((c,i)=>coupon(c,i,false,idx)).join('')+end(),bottom:gift?`<div class="total-strip"><span>合计金额 <b>¥ ${state.coupon<0?0:state.coupon===1?30:state.coupon===2?9:50}.00</b></span><button class="text-blue" data-act="gift-coupon">确认赠送</button></div>`:''};}
