function openFilter(label){if(label==='筛选'){advancedFilter();return}let options=filterOptions[label]||['全部','是','否'];if(label==='状态'){if(['doctors','doctor-pools'].includes(current))options=['全部','待激活','已激活','已流失','未注册'];else if(current.includes('workorder'))options=['全部','待反馈','待确认','已完成','已退回','已转派'];else if(current.startsWith('after-sale'))options=['全部','未完成','已完成'];else if(current==='reward-pool')options=['全部','未领取','已领取'];}
choice(label,options,i=>{const v=options[i];if(v==='自定义时间'){sheet('自定义时间',`<div class="field"><label>开始日期</label><input id="filter-start" type="date" value="2026-11-01"></div><div class="field"><label>结束日期</label><input id="filter-end" type="date" value="2026-11-06"></div>${act('custom-date','完成','primary-btn',label)}`);return}state.filters[current]??={};state.filters[current][label]=v;save();render();});}
function advancedFilter(){const groups=current.includes('order')?{'开票状态':['全部','未申请','已申请','禁止申请'],'粉剂包装样式':['全部','普通包装','独立包装'],'药库':['全部','示例药房一','示例药房二'],'医助':['全部医助','青禾','小川'],'继承关系':['全部','继承','非继承']}:current==='potential-doctors'?{'地区':['全部','浙江省 杭州市','浙江省 宁波市'],'职称':['全部','主治医师','副主任医师','主任医师'],'医生类型':['全部','执业医师','助理医师'],'患者数量':['全部','较高','中等'],'开方潜力':['全部','较高','中等'],'沟通态度':['全部','积极','一般'],'平台态度':['全部','认可','待沟通']}:{'生命周期':['全部','新注册','成长期','稳定期'],'活跃状态':['全部','待激活','已激活','已流失'],'医生等级':['全部','A级','B级','C级'],'医生来源':['全部','自主开发','转介绍'],'标签':['全部','重点跟进','开方意愿高','学术活动'],'未开剂型':['全部','普通方','膏方','中成药']};state.pendingFilters={...state.filters[current]};sheet('筛选',Object.entries(groups).map(([title,opts])=>`<div class="sheet-filter-group"><h4>${title}</h4><div class="chips">${opts.map((x,i)=>`<button class="chip ${state.pendingFilters[title]===x||(!state.pendingFilters[title]&&i===0)?'active':''}" data-filter-chip="${title}" data-value="${x}">${x}</button>`).join('')}</div></div>`).join('')+`<div class="sheet-filter-actions">${act('reset-filter-sheet','重置')}${act('apply-filter-sheet','完成','primary')}</div>`);}
function performSearch(){const input=$('#native-search');const value=input?.value.trim()||state.queries[current]||'';if(!value){toast('请输入搜索内容');input?.focus();return}state.queries[current]=value;const h=state.histories[current]||[];state.histories[current]=[value,...h.filter(x=>x!==value)].slice(0,8);save();let id=queryResults[current];if(current==='order-search'&&state.settings.searchOrigin==='photo-orders')id='photo-search-results';if(['hospital-search','select-manager','select-unverified','workorder-select-person'].includes(current)){render();return}if(id){if(id==='doctor-search-results')state.queries[id]=value;navigate(id)}else {render();toast('已更新搜索结果');}}
function selectResult(value,index){const target=state.selectionTarget;if(target){state.formValues[target.page]={...valuesFor(target.page),[target.field]:value};state.selectionTarget=null;navigate(target.page);return}if(current==='department-select'){navigate('doctor-add');return}if(current==='hospital-search'){state.formValues['doctor-add']={...valuesFor('doctor-add'),hospital:value};navigate('doctor-add');return}if(current==='select-manager'){state.formValues['change-manager']={...valuesFor('change-manager'),manager:value};navigate('change-manager');return}if(current==='workorder-select-person'){state.formValues['workorder-transfer']={...valuesFor('workorder-transfer'),person:value};navigate('workorder-transfer');return}if(current==='select-unverified'){state.formValues['doctor-audit']={...valuesFor('doctor-audit'),doctor:value};navigate('doctor-audit');return}state.queries[current]=value;performSearchWith(value);}
function performSearchWith(value){state.queries[current]=value;const input=$('#native-search');if(input)input.value=value;performSearch();}
function demoSvg(label='演示附件'){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="400" height="280"><rect width="400" height="280" fill="#edf4fc"/><rect x="35" y="35" width="330" height="210" rx="10" fill="white" stroke="#c9dced"/><path d="M95 180l60-55 40 35 55-60 60 80" fill="none" stroke="#9ac4e9" stroke-width="5"/><circle cx="128" cy="85" r="15" fill="#bdd9ef"/><text x="200" y="220" font-family="sans-serif" font-size="17" text-anchor="middle" fill="#8fa6c0">${esc(label)} · 本地演示</text></svg>`);}
function addDemoUpload(key){const f=fieldsFor(current).find(f=>f.key===key);if(!f)return;readForm();state.uploads[current]??={};state.uploads[current][key]??=[];if(state.uploads[current][key].length>=f.max){toast('已达到图片数量上限');return}state.uploads[current][key].push(demoSvg(f.label));save();render();}
function drawQR(){const canvas=$('#invite-qr');if(!canvas)return;const ctx=canvas.getContext('2d'),n=29,k=6,offset=18;ctx.fillStyle='#fff';ctx.fillRect(0,0,210,210);ctx.fillStyle='#3d536e';for(let y=0;y<n;y++)for(let x=0;x<n;x++){if(((x*17+y*31+x*y*3)%7)<3)ctx.fillRect(offset+x*k,offset+y*k,k,k)}for(const [x,y]of [[0,0],[22,0],[0,22]]){ctx.fillStyle='#fff';ctx.fillRect(offset+(x-1)*k,offset+(y-1)*k,9*k,9*k);ctx.fillStyle='#344c68';ctx.fillRect(offset+x*k,offset+y*k,7*k,7*k);ctx.fillStyle='#fff';ctx.fillRect(offset+(x+1)*k,offset+(y+1)*k,5*k,5*k);ctx.fillStyle='#344c68';ctx.fillRect(offset+(x+2)*k,offset+(y+2)*k,3*k,3*k)}}
function showAtlas(){const needle=$('#page-search').value.trim();$('#atlas').hidden=false;$('#atlas').innerHTML=`<div class="atlas-top"><div><div class="eyebrow">CRM · 页面地图</div><h2>按业务模块探索全部页面</h2><p class="atlas-intro">${pages.length} 个页面或明确状态 · 点击页面进入交互预览</p></div>${act('close-atlas','关闭总览','desktop-btn')}</div>${CRM_META.modules.map((m,i)=>`<section class="atlas-group"><h3>${String(i+1).padStart(2,'0')}　${m}</h3><div class="atlas-grid">${pages.filter(p=>p.module===m&&(!needle||p.name.includes(needle))).map(p=>go(p.id,`<span class="n">${String(pages.indexOf(p)+1).padStart(3,'0')}</span><span><strong>${p.name}</strong><small>${p.kind} · ${p.figma?'Figma + iOS':'iOS'}</small></span>`,'atlas-card')).join('')}</div></section>`).join('')}`;}
function back(){if(state.selectionTarget){const id=state.selectionTarget.page;state.selectionTarget=null;navigate(id,{replace:true});return}const prev=stack.pop();navigate(prev||tabRoot(byId[current]),{replace:true});}
function action(name,value='',el=null){
switch(name){
case 'back':back();break;case 'close-overlay':closeOverlay();break;case 'dialog-ok':{const cb=overlayReturn;closeOverlay();if(cb)cb();break;}case 'close-atlas':$('#atlas').hidden=true;break;
case 'retry':state.viewState='normal';$('#state-select').value='normal';render();toast('已重新加载');break;
case 'scope':{let opts;if(current==='doctor-pools')opts=['私有池','公有池','死海'];else if(current==='doctors')opts=state.role==='manager'?['我的医生','代理医生','团队医生','区域医生']:['我的医生','代理医生'];else opts=state.role==='manager'?['我的订单','代理订单','团队订单','区域订单','我的照片方','商城订单']:['我的订单','代理订单','我的照片方','商城订单'];choice('查看范围',opts,i=>{state.filters[current]??={};state.filters[current][current==='doctor-pools'?'客户池':'责任范围']=opts[i];if(opts[i]==='我的照片方')navigate('photo-orders');else if(opts[i]==='商城订单')navigate('mall-orders');else{render();const t=$('.navbar .nav-title button');if(t)t.innerHTML=esc(opts[i])+' <small>⌄</small>';}});break;}
case 'metric-scope':choice('统计范围',state.role==='manager'?['今日 | 个人','本月 | 个人','本月 | 我的团队','本月 | 我的区域']:['今日 | 个人','本月 | 个人'],i=>{state.settings.metricScope=['今日 | 个人','本月 | 个人','本月 | 我的团队','本月 | 我的区域'][i];render();});break;
case 'expand-metrics':state.settings.expandedMetrics=!state.settings.expandedMetrics;render();break;case 'chart-value':toast('当前数据：'+value);break;
case 'home-metric':state.selectedDoctor=Number(value);navigate('doctor-income-orders');break;
case 'date-filter':openFilter('日期');break;case 'advanced-filter':case 'work-filter':advancedFilter();break;case 'clear-filters':state.filters[current]={};render();break;
case 'apply-filter-sheet':state.filters[current]={...state.pendingFilters};state.pendingFilters={};closeOverlay();render();toast('筛选已更新');break;
case 'reset-filter-sheet':state.pendingFilters={};$$('#overlay-root .sheet-filter-group').forEach(g=>{g.querySelectorAll('.chip').forEach((b,i)=>b.classList.toggle('active',i===0))});break;
case 'custom-date':{const start=$('#filter-start').value,endDate=$('#filter-end').value;if(!start||!endDate||endDate<start){toast('请选择有效的开始和结束日期');break}state.filters[current]??={};state.filters[current][value]=start.slice(5)+' 至 '+endDate.slice(5);closeOverlay();render();break;}
case 'read-all':confirm('全部设为已读？','将当前演示中的未读通知设为已读。',()=>{state.read=['all'];render();toast('全部未读已设置为已读');});break;
case 'todo-toggle':{const id=Number(value);state.doneTodo=state.doneTodo.includes(id)?state.doneTodo.filter(x=>x!==id):[...state.doneTodo,id];render();break;}
case 'month-prev':state.month--;if(state.month===0){state.month=12;state.year--}render();break;case 'month-next':state.month++;if(state.month===13){state.month=1;state.year++}render();break;
case 'month-select':openFilter('月份');break;
case 'view-visit':{const rec=[...state.visits,{doctor:doctor().name,date:'2026-11-04',way:'线下',hospital:doctor().hospital,purpose:'日常维护',content:'沟通近期门诊情况，了解平台使用需求。',nextFocus:'跟进首次开方情况'}][Number(value)]||state.visits[0];if(rec){state.formValues['visit-edit']={...valuesFor('visit-edit'),...rec};navigate('visit-edit')}else navigate('visit-edit');break;}
case 'delete-schedule':confirm('确认删除？','删除当前本地演示日程或生日提醒。',()=>{state.schedules.shift();navigate('calendar');toast('已删除演示安排');});break;
case 'call':confirm('拨打电话',value||doctor().phone,()=>toast('原型已演示拨号确认，不发起真实通话'),'拨打');break;
case 'copy-order':copyText(order().id);break;case 'copy-tracking':copyText('SF000000000000');break;case 'tracking-site':info('物流信息','原型展示物流查询入口，不访问真实订单或快递服务。');break;
case 'follow-order':{const id=order().id;state.followed=state.followed.includes(id)?state.followed.filter(x=>x!==id):[...state.followed,id];render();toast(state.followed.includes(id)?'已关注订单':'已取消关注');break;}
case 'order-menu':{const opts=['催付款','修改收货地址','开发票','紧急退款','药方溯源','用药单详情','查看面单'];choice('订单操作',opts,i=>{if(i===0)confirm('确认催付款？','原型仅演示确认，不向患者发送消息。',()=>toast('已记录演示催付操作'));else navigate(['','order-address','order-invoice','order-refund','order-prescription-trace','order-image','order-image'][i]);});break;}
case 'price-details':state.settings.priceExpanded=!state.settings.priceExpanded;render();break;
case 'preview-image':showImage(demoSvg('演示图片'));break;case 'save-image':download('演示图片.svg',decodeURIComponent(demoSvg('演示图片').split(',')[1]),'image/svg+xml');toast('已下载演示图片');break;
case 'download-document':download('CRM-演示资料.txt','CRM 交互设计演示资料\n本文件不含内部业务资料。\n用于演示附件下载、预览和返回交互。','text/plain;charset=utf-8');toast('已下载演示资料');break;
case 'claim':{const n=value||doctor().name;if(state.claimed.includes(n)){toast('该医生已领取');break}if(current==='reward-pool'&&state.cards<2){info('兑换卡不足','当前演示兑换卡不足，暂时无法领取。');break}confirm('确认领取“'+n+'”医生？',current==='reward-pool'?'领取该医生需要消耗2张兑换卡。':'请确认领取该医生并安排后续跟进。',()=>{state.claimed.push(n);if(current==='reward-pool')state.cards-=2;render();toast('领取成功');});break;}
case 'protect':{const n=value||doctor().name;const exists=state.protected.includes(n);confirm(exists?'确认取消保护？':'确认保护该医生？',exists?'取消后按业务规则参与客户池流转。当前仅演示状态。':'将该医生设为保护状态。当前仅更新本地演示。',()=>{state.protected=exists?state.protected.filter(x=>x!==n):[...state.protected,n];render();toast(exists?'已取消保护':'已设为保护');});break;}
case 'potential-reason':info('推荐原因',`<h4>${esc(value||doctor().name)}</h4>演示画像：患者量较高、对平台有进一步了解意愿，建议结合历史拜访内容开展跟进。`);break;
case 'release-doctor':confirm('公私海转移确认','确认将该医生释放到公有池？本次只改变原型演示。',()=>{state.settings.releasedDoctor=doctor().name;toast('已演示释放至公有池');});break;
case 'doctor-delete':confirm('删除医生确认','是否确定删除当前本地演示医生资料？',()=>{const n=doctor().name;state.newDoctors=state.newDoctors.filter(d=>d.name!==n);state.removedDoctors??=[];state.removedDoctors.push(n);state.selectedDoctor=0;navigate('doctors');toast('已演示删除确认');});break;
case 'account-toggle':{const key=value;if(state.settings[key])confirm('关闭'+key+'？','确认后更新该项演示设置。',()=>{state.settings[key]=false;render();});else{state.settings[key]=true;render();}break;}
case 'account-option':{const label=el?.querySelector('.label')?.textContent||'活动类型';const opts=label==='医生类型'?['普通医生','重点医生']:label==='第三方微信提现渠道'?['默认渠道','备用渠道']:['未设置','平台活动','非平台活动'];choice(label,opts,i=>{state.settings[label]=opts[i];render();toast('已选择：'+opts[i]);});break;}
case 'tax-option':choice('纳税方式',['代扣代缴','自行申报'],i=>{confirm('确认更改纳税方式？','生效时间及修改次数以实际业务规则为准，本次演示只更新展示。',()=>{state.settings.taxType=['代扣代缴','自行申报'][i];render();toast('纳税方式已更新');});});break;
case 'patient-menu':choice('患者管理',['删除患者','恢复患者'],i=>confirm('确认'+(i?'恢复':'删除')+'患者？','当前仅演示操作，不处理真实患者资料。',()=>toast('已演示'+(i?'恢复':'删除')+'操作')));break;
case 'attention-toggle':state.settings['attention-'+value]=!state.settings['attention-'+value];render();break;case 'save-account':navigate('doctor-account');toast('设置已保存');break;
case 'generate-materials':{const selected=$$('.material-option:checked').map(x=>x.value);if(!selected.length){toast('请选择要生成的物料');break}info('物料已生成',selected.map(x=>'<p>'+x+' · 演示文件</p>').join(''));break;}
case 'coupon-info':info('优惠券信息','查看券面金额、适用条件及有效期。实际可用性以订单核算为准。');break;
case 'gift-coupon':if(state.coupon<0){toast('请选择优惠券');break}confirm('确认赠送优惠券？','将所选单张券赠送给当前医生。',()=>{state.gifts.push({doctor:doctor().name,coupon:state.coupon});navigate('coupon-list');toast('赠送成功，已记录演示赠券');});break;
case 'tag-add':if(state.tags.length>=10){toast('自定义标签最多添加10个');break}tagEditor();break;case 'tag-edit':tagEditor(Number(value));break;
case 'tag-save':{const input=$('#tag-input'),text=input.value.trim(),idx=Number(input.dataset.index);if(!text){toast('请输入标签名');break}if(state.tags.includes(text)&&state.tags[idx]!==text){toast('该标签已存在');break}const commit=()=>{if(idx>=0)state.tags[idx]=text;else state.tags.push(text);closeOverlay();render();toast('标签已保存')};if(idx>=0)confirm('确认修改标签？','对应医生的标签显示将随之更新。当前只修改本地演示。',commit);else commit();break;}
case 'tag-delete':confirm('确认删除标签？','删除后对应医生的标签也会更新。当前只修改本地演示。',()=>{state.tags.splice(Number(value),1);render();toast('标签已删除');});break;
case 'demo-upload':addDemoUpload(value);break;
case 'register-code':{const phone=$('#register-phone').value.trim();if(!/^1\d{10}$/.test(phone)){toast('请输入正确的医生手机号');break}state.settings.registerPhone=phone;state.settings.registerCode=true;render();toast('已展示演示验证码');break;}
case 'send-code':{const phone=$('#login-phone').value.trim();if(!/^1\d{10}$/.test(phone)){toast('请输入正确的手机号');break}$('#login-code').value='123456';toast('演示验证码：123456，不发送短信');break;}
case 'privacy':info('用户隐私协议','这里保留正式应用的协议入口。当前文件为本地交互演示，不替代正式用户协议，不收集或发送登录信息。');break;
case 'ding-login':confirm('钉钉授权登录','原型模拟授权成功后的登录结果，不调用钉钉账号。',()=>{navigate('home');toast('已进入演示账号');},'模拟授权');break;
case 'logout':confirm('确认退出登录？','将返回原型登录页面。',()=>navigate('login'));break;case 'check-update':toast('当前演示版本已是最新版本');break;
case 'save-settings':save();toast('消息设置已保存');break;
case 'notice-level':{const opts=['紧急消息','一般消息','关闭通知'];choice(value,opts,i=>{state.settings['notice-'+value]=opts[i];render();});break;}
case 'approval-pass':case 'approval-reject':{const pass=name==='approval-pass';confirm(pass?'是否确认通过？':'是否确认不通过？','请核对申请内容。本次仅更新本地演示审批状态。',()=>{state.approved[doctor().name]=pass?'审批通过':'审批不通过';render();toast(pass?'已通过演示审批':'已记录不通过');});break;}
case 'reject-audit':confirm('驳回确认','确认驳回当前演示医生的认证审核？',()=>{toast('已演示驳回操作');});break;
case 'thanks-approve':choice('审核感谢信',['审核通过','审核不通过'],i=>confirm('确认'+(i?'审核不通过':'审核通过')+'？',i?'不通过会撤销感谢信。当前只演示状态。':'审核通过后会发放给医生。当前只演示状态。',()=>toast('已记录演示审核结果')));break;
case 'activity-rules':info('提报规则','<h4>运营活动提报规则</h4>正式规则由服务端提供。原型展示规则阅读及关闭交互，实际适用范围、提报条件和审批流程需以业务确认内容为准。');break;
case 'balance-info':info('余额说明','原型展示基金池余额、本月申报、预算入账及实际消耗的关系。金额为演示数据，不作为财务余额。');break;
case 'reward-rules':sheet('规则说明',`<div class="rule-text"><h4>奖励池</h4>符合条件时可使用兑换卡领取医生。领取前核对兑换卡消耗数量，领取后查看记录。<p>具体发卡、积分及领取规则以服务端下发规则为准。</p></div>${state.role==='manager'?go('reward-rules','修改规则','primary-btn outline'):''}${act('close-overlay','我知道了','primary-btn')}`);break;
case 'create-work-type':choice('选择工单类型',['订单处理','物流协同','医生资料协同','其他'],i=>{state.formValues['workorder-create']={...valuesFor('workorder-create'),category:['订单处理','物流协同','医生资料协同','其他'][i]};navigate('workorder-create');});break;
case 'send-chat':{const el=$('#chat-text'),text=el.value.trim();if(!text){toast('消息不能为空');break}state.workMessages.push({text,self:true,time:'刚刚'});save();render();$('#app-scroll').scrollTop=$('#app-scroll').scrollHeight;toast('消息已发送（演示）');break;}
case 'chat-attachment':choice('添加附件',['演示图片','演示文件'],i=>{state.workMessages.push(i===0?{image:demoSvg('工单附件'),self:true,time:'刚刚'}:{file:true,self:true,time:'刚刚'});render();$('#app-scroll').scrollTop=$('#app-scroll').scrollHeight;});break;
case 'delete-work':confirm('请确认是否删除该工单','删除当前本地演示工单。',()=>{state.workDeleted=true;state.workorders=[];navigate('workorders');toast('工单已删除');});break;
case 'members-done':navigate('pk-create');toast('队员选择已回填');break;
case 'member-up':case 'member-down':{const idx=Number(value),to=idx+(name==='member-up'?-1:1);if(to>=0&&to<state.selectedMembers.length){readForm();[state.selectedMembers[idx],state.selectedMembers[to]]=[state.selectedMembers[to],state.selectedMembers[idx]];render();}break;}
case 'pk-menu':choice('对战操作',['查看排名','查看队伍','删除对战'],i=>{if(i===2)confirm('确认删除对战？','仅删除当前本地演示对战。',()=>{if(state.pkEntries.length)state.pkEntries.shift();else state.settings.pkDeleted=true;navigate('pk-center');toast('已演示删除操作');});else navigate(i===0?'pk-ranking':'pk-team-detail');});break;
case 'pause-warning':choice('暂不预警时间',['7天','15天','30天'],i=>{state.settings.noWarningUntil=['7天后','15天后','30天后'][i];render();toast('预警处理已保存');});break;
case 'map-marker':state.selectedDoctor=Number(value);render();break;case 'locate':toast('已回到演示位置');break;case 'map-search':{const val=$('#map-input').value.trim();if(!val){toast('请输入搜索地点');break}state.settings.mapAddress=val;render();break;}
case 'save-map':navigate('doctor-info');toast('拜访地址已保存');break;
case 'drug-search':state.queries.drug=$('#drug-search').value.trim();render();break;
case 'perform-search':performSearch();break;case 'clear-native-search':state.queries[current]='';render();$('#native-search')?.focus();break;
case 'clear-history':confirm('清空搜索历史？','仅清空当前原型的本地搜索记录。',()=>{state.histories[current]=[];render();});break;
case 'field-info':info('页面信息','该字段由接口返回或与对应页面交互。当前原型保留入口和字段关系。');break;
default:toast('已选择 '+(value||name));
}save();}
function tagEditor(index=-1){sheet(index<0?'新增标签':'修改标签',`<div class="field"><input id="tag-input" data-index="${index}" value="${esc(state.tags[index]||'')}" placeholder="请输入标签名称" maxlength="12" aria-label="标签名称"></div>${act('tag-save','保存','primary-btn')}`);}
function copyText(text){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast('已复制')).catch(()=>toast('复制内容：'+text));else toast('复制内容：'+text);}
function download(name,content,mime){const blob=new Blob([content],{type:mime});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{
const target=e.target instanceof Element?e.target:null;if(!target)return;
if(target.matches('[data-close-overlay]')){closeOverlay();return}
let el;
if((el=target.closest('[data-go]'))){e.preventDefault();if($('#native-form'))readForm();const next=el.dataset.go;if(next==='doctor-add')state.editingDoctor=current==='doctor-info';if(['orders','photo-orders','focused-orders','mall-orders'].includes(current)&&next.includes('search'))state.settings.searchOrigin=current;if(current==='doctor-info'&&next==='doctor-add')state.formValues['doctor-add']={...valuesFor('doctor-add'),...doctor(),gender:'男',region:'浙江省 杭州市 西湖区',manager:'青禾'};$('#atlas').hidden=true;navigate(next);if(next==='doctor-invite')requestAnimationFrame(drawQR);return}
if((el=target.closest('[data-act]'))){e.preventDefault();action(el.dataset.act,el.dataset.value||'',el);return}
if((el=target.closest('[data-pick]'))){e.preventDefault();const cb=overlayReturn,i=Number(el.dataset.pick);closeOverlay();cb?.(i);return}
if((el=target.closest('[data-filter]'))){e.preventDefault();openFilter(el.dataset.filter);return}
if((el=target.closest('[data-tab]'))){e.preventDefault();state.tabs[el.dataset.tab]=Number(el.dataset.index);render();return}
if((el=target.closest('[data-doctor]'))){e.preventDefault();state.selectedDoctor=Number(el.dataset.doctor);if(state.selectionTarget){selectResult(doctor().name,state.selectedDoctor)}else navigate(el.dataset.target||'doctor-home');return}
if((el=target.closest('[data-order]'))){e.preventDefault();state.selectedOrder=Number(el.dataset.order);navigate(el.dataset.target||'order-detail');return}
if((el=target.closest('[data-work]'))){e.preventDefault();state.selectedWork=Number(el.dataset.work);navigate('workorder-chat');return}
if((el=target.closest('[data-module]'))){el.closest('.module-group').classList.toggle('collapsed');return}
if((el=target.closest('[data-day]'))){state.day=Number(el.dataset.day);render();return}
if((el=target.closest('[data-form-chip]'))){e.preventDefault();const v=readForm(),key=el.dataset.formChip,text=el.dataset.value;if(el.dataset.multi==='true'){let a=Array.isArray(v[key])?v[key]:[];v[key]=a.includes(text)?a.filter(x=>x!==text):[...a,text]}else v[key]=text;state.formValues[current]=v;render();return}
if((el=target.closest('[data-form-switch]'))){e.preventDefault();const v=readForm();v[el.dataset.formSwitch]=!v[el.dataset.formSwitch];state.formValues[current]=v;render();return}
if((el=target.closest('[data-select-page]'))){e.preventDefault();readForm();state.selectionTarget={page:current,field:el.dataset.field};navigate(el.dataset.selectPage);return}
if((el=target.closest('[data-search-result]'))){e.preventDefault();selectResult(el.dataset.searchResult,Number(el.dataset.index));return}
if((el=target.closest('[data-search-history]'))){e.preventDefault();performSearchWith(el.dataset.searchHistory);return}
if((el=target.closest('[data-coupon-tab]'))){state.tabs.coupons=Number(el.dataset.couponTab);navigate('coupon-list');return}
if((el=target.closest('[data-coupon]'))){state.coupon=Number(el.dataset.coupon);render();return}
if((el=target.closest('[data-bill-month]'))){state.billMonth=el.dataset.billMonth;navigate('month-bill-detail');return}
if((el=target.closest('[data-member]'))){const n=el.dataset.member;state.selectedMembers=state.selectedMembers.includes(n)?state.selectedMembers.filter(x=>x!==n):[...state.selectedMembers,n];render();return}
if((el=target.closest('[data-preview]'))){showImage(el.dataset.preview);return}
if((el=target.closest('[data-remove-upload]'))){e.preventDefault();readForm();state.uploads[current]?.[el.dataset.removeUpload]?.splice(Number(el.dataset.index),1);render();return}
if((el=target.closest('[data-filter-chip]'))){state.pendingFilters[el.dataset.filterChip]=el.dataset.value;el.parentElement.querySelectorAll('.chip').forEach(b=>b.classList.toggle('active',b===el));return}
if((el=target.closest('[data-pool]'))){state.filters['doctor-pools']??={};state.filters['doctor-pools']['客户池']=el.dataset.pool==='public'?'公有池':'私有池';navigate('doctor-pools');return}
if((el=target.closest('[data-size]'))){document.documentElement.style.setProperty('--phone-width',el.dataset.size+'px');$$('#size-control button').forEach(b=>b.classList.toggle('selected',b===el));return}
});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='native-form'){submitForm();return}if(e.target.id==='login-form'){if(!/^1\d{10}$/.test($('#login-phone').value.trim())){toast('请输入正确的手机号');return}if(!$('#login-code').value.trim()){toast('请输入验证码');return}if(!$('#login-agree').checked){toast('请先阅读并同意协议');return}navigate('home');toast('已进入演示账号')}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='page-search'){renderCatalog();return}if(t.id==='native-search'){state.queries[current]=t.value;return}if(t.closest('#native-form')){state.formValues[current]={...valuesFor(current),[t.name]:t.value};const counter=$(`[data-counter="${t.name}"]`),f=fieldsFor(current).find(f=>f.key===t.name);if(counter)counter.textContent=t.value.length+(f?.max?'/'+f.max:'');save();}if(t.id==='chat-text'){t.style.height='34px';t.style.height=Math.min(96,t.scrollHeight)+'px';}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset?.upload){readForm();const f=fieldsFor(current).find(f=>f.key===t.dataset.upload),page=current,key=t.dataset.upload;state.uploads[page]??={};const list=state.uploads[page][key]||[];const files=[...t.files].slice(0,f.max-list.length);const results=await Promise.all(files.map(file=>new Promise(resolve=>{if(!file.type.startsWith('image/')){resolve(null);return}const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>resolve(null);r.readAsDataURL(file)})));state.uploads[page][key]=[...list,...results.filter(Boolean)];save();if(current===page)render();return}if(t.closest('#native-form')&&t.tagName==='SELECT'){readForm();render();return}if(t.id==='work-persona'){state.workRole=t.value;render();return}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#page-search').focus()}if(e.key==='Escape'){closeOverlay();$('#atlas').hidden=true}if(e.key==='Enter'&&e.target.id==='native-search'){e.preventDefault();performSearch()}if(e.key==='Enter'&&e.target.id==='drug-search'){e.preventDefault();action('drug-search')}});
$('#role-select').addEventListener('change',e=>{state.role=e.target.value;render()});$('#state-select').addEventListener('change',e=>{state.viewState=e.target.value;render()});$('#map-btn').addEventListener('click',showAtlas);$('#focus-btn').addEventListener('click',()=>{document.body.classList.toggle('focus-mode');$('#focus-btn').textContent=document.body.classList.contains('focus-mode')?'返回设计工作台':'专注预览'});$('#reset-btn').addEventListener('click',()=>confirm('重置演示数据？','将清除本原型的演示修改、表单和筛选，恢复初始内容。',()=>{state=defaults();save();navigate('home',{replace:true});toast('演示数据已重置')}));
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(byId[id]&&id!==current){current=id;closeOverlay();render();if(id==='doctor-invite')requestAnimationFrame(drawQR)}});
current=byId[location.hash.slice(1)]?location.hash.slice(1):'home';render();if(current==='doctor-invite')requestAnimationFrame(drawQR);
window.CRMPrototype={get current(){return current},get pageCount(){return pages.length},get routeIds(){return pages.map(p=>p.id)},get state(){return JSON.parse(JSON.stringify(state))}};
